type CartItem = { id: string; qty: number; price: number }

export function cartTotal(items: CartItem[]) {
  return items.reduce((sum, i) => sum + i.qty * i.price, 0)
}

export function upsertItem(items: CartItem[], incoming: CartItem) {
  const idx = items.findIndex(i => i.id === incoming.id)
  if (idx === -1) return [...items, incoming]
  const next = [...items]
  next[idx] = { ...next[idx], qty: next[idx].qty + incoming.qty }
  return next
}

let queue = Promise.resolve()

export function enqueueCartMutation<T>(task: () => Promise<T>): Promise<T> {
  queue = queue.then(task as any).catch(() => undefined as any)
  return queue as Promise<T>
}
